const DRAFT_CHAT_ID = '-1003839420608';
const updateType = $json.channel_post ? 'channel_post' : ($json.message ? 'message' : 'unknown');
const msg = $json.channel_post || $json.message || $json;

const incomingChatId = String(msg.chat?.id || '');
const senderChatId = String(msg.sender_chat?.id || '');
const forwardFromChatId = String(msg.forward_from_chat?.id || '');
const fromUserId = String(msg.from?.id || '');

console.log('ForgeView YouTube upload chat validation', {
  updateType,
  incomingChatId,
  senderChatId,
  forwardFromChatId,
  fromUserId,
  expectedDraftChatId: DRAFT_CHAT_ID,
});

const acceptedChatIds = [incomingChatId, senderChatId, forwardFromChatId].filter(Boolean);
if (!acceptedChatIds.includes(DRAFT_CHAT_ID)) {
  throw new Error(`Ignoring Telegram update not intended for drafts. incoming chat_id=${incomingChatId || 'missing'}, sender_chat_id=${senderChatId || 'missing'}, forward_from_chat_id=${forwardFromChatId || 'missing'}, from_user_id=${fromUserId || 'missing'}, expected=${DRAFT_CHAT_ID}`);
}

const video = msg.video || msg.document || {};
const fileId = video.file_id;
if (!fileId) {
  throw new Error('No Telegram MP4 video/document file_id found. Send short.mp4 as a video or document to the draft channel.');
}

const caption = msg.caption || '';

function extractBlock(label) {
  const pattern = new RegExp(`${label}\\s*:\\s*([\\s\\S]*?)(?=\\n[A-Z_ ]{3,}\\s*:|$)`, 'i');
  const match = caption.match(pattern);
  return match ? match[1].trim() : '';
}

let title = extractBlock('TITLE') || extractBlock('YOUTUBE TITLE') || 'ForgeView Bot Reliability Lesson #Shorts';
title = title.replace(/\s+/g, ' ').trim();
if (!/#Shorts/i.test(title)) title = `${title} #Shorts`;
if (title.length > 100) title = title.slice(0, 97).trimEnd() + '...';

let description = extractBlock('DESCRIPTION') || extractBlock('YOUTUBE DESCRIPTION') || caption.trim();
if (!description) {
  description = 'A practical ForgeView lesson from building AI automation systems, trading bots, and workflows in public.';
}

const requiredLines = [
  '#Shorts',
  '',
  'Telegram:',
  'https://t.me/ForgeViewCom',
  '',
  'X:',
  'https://x.com/ForgeViewX'
];

for (const line of requiredLines) {
  if (line && !description.includes(line)) {
    description += `\n${line}`;
  } else if (!line) {
    description += '\n';
  }
}

description = description.replace(/\n{3,}/g, '\n\n').trim();

return [{
  json: {
    draft_chat_id: DRAFT_CHAT_ID,
    update_type: updateType,
    incoming_chat_id: incomingChatId,
    sender_chat_id: senderChatId,
    forward_from_chat_id: forwardFromChatId,
    from_user_id: fromUserId,
    source_message_id: msg.message_id,
    video_file_id: fileId,
    title,
    description,
    privacyStatus: 'private',
    categoryId: '28'
  }
}];

const upload = $json;
const videoId = upload.id || upload.videoId || upload.snippet?.resourceId?.videoId || '';
const url = videoId ? `https://www.youtube.com/watch?v=${videoId}` : 'URL unavailable';

return [{
  json: {
    draft_chat_id: '-1003839420608',
    video_id: videoId,
    video_url: url,
    confirmation_text: `UPLOAD SUCCESS\n\nVideo ID:\n${videoId || 'unknown'}\n\nURL:\n${url}`
  }
}];
